using FluNET.Compilation.Inference;using FluNET.Language;using FluNET.Language.Resources;using FluNET.Prompt;using FluNET.Prompt.Expressions;using FluNET.Prompt.Surface;namespace FluNET.Compilation.Lowering;public sealed class SurfaceLowerer{private readonly InferenceEngine i;private readonly IResourceProviderRegistry p;public SurfaceLowerer(IResourceProviderRegistry providers):this(new InferenceEngine(),providers){}public SurfaceLowerer(InferenceEngine inference,IResourceProviderRegistry providers){i=inference;p=providers;}public LoweringResult Lower(SurfaceParseResult parse,PromptGrammar grammar,LanguageSnapshot language){List<CommandSyntax>c=[];List<CommandLinkSyntax>l=[];List<SourceMapEntry>m=[];List<SurfaceDiagnostic>d=[..parse.Diagnostics];InferenceTrace t=new();LowerStatements(parse.Program.Statements,new(null,null,null,null),new Dictionary<string,Uri>(StringComparer.OrdinalIgnoreCase),grammar,language,c,l,m,t,d);return new(parse.Document,parse.Program,new PromptSyntax(c,l),new SourceMap(m),t,d);}
private void LowerStatements(IReadOnlyList<SurfaceStatementSyntax>s,LoweringContext inherited,IDictionary<string,Uri>b,PromptGrammar g,LanguageSnapshot lang,List<CommandSyntax>c,List<CommandLinkSyntax>links,List<SourceMapEntry>map,InferenceTrace trace,List<SurfaceDiagnostic>d){LoweringContext current=inherited;string?implicitOutput=null;foreach(var st in s){if(st is SurfaceContextSyntax ctx){if(!TryResolveBase(ctx.BaseResource.UnquotedText,current.BaseUri,out Uri?u)){d.Add(new("FLN240",$"Invalid FROM base '{ctx.BaseResource.Text}'.",ctx.BaseResource.Span));continue;}LowerStatements(ctx.Statements,current with{BaseUri=u},b,g,lang,c,links,map,trace,d);implicitOutput=null;continue;}if(st is SurfacePipelineSyntax pipe){implicitOutput=LowerPipeline(pipe,current,b,g,lang,c,links,map,trace,d);continue;}if(st is not SurfaceCommandSyntax command)continue;if(ApplyDirective(command,ref current,b,d))continue;SurfaceCommandSyntax e=command;if(SurfaceDataLowering.IsDataStage(e)&&e.NormalizedName is not("JOIN"or"MATCH")&&implicitOutput is null){d.Add(new("FLN263",$"{e.Name} requires a previous data value.",e.Span));continue;}if(e.NormalizedName=="SAY"&&e.Values.Count==0&&implicitOutput is not null)e=InjectValue(e,implicitOutput);IReadOnlyList<CommandSyntax>lowered=SurfaceDataLowering.IsDataStage(e)?LowerData(e,implicitOutput??string.Empty,e.Alias??NextPipe(c.Count),g,d):LowerCommand(e,current,b,g,lang,trace,d);if(lowered.Count==0)continue;Append(lowered,command.Span,current,g,c,links,map);implicitOutput=ProducedVariable(e,lowered)??implicitOutput;}}
private string?LowerPipeline(SurfacePipelineSyntax pipe,LoweringContext ctx,IDictionary<string,Uri>b,PromptGrammar g,LanguageSnapshot lang,List<CommandSyntax>c,List<CommandLinkSyntax>links,List<SourceMapEntry>map,InferenceTrace trace,List<SurfaceDiagnostic>d){string?value=null;foreach(SurfaceCommandSyntax stage in pipe.Stages){SurfaceCommandSyntax e=stage;IReadOnlyList<CommandSyntax>lowered;if(SurfaceDataLowering.IsDataStage(stage)){if(value is null&&stage.NormalizedName is not("JOIN"or"MATCH")){d.Add(new("FLN251",$"Pipeline stage '{stage.Name}' has no previous value.",stage.Span));return null;}lowered=LowerData(stage,value??string.Empty,stage.Alias??NextPipe(c.Count),g,d);}else{if(value is not null&&stage.NormalizedName=="SAY"&&stage.Values.Count==0)e=InjectValue(stage,value);else if(value is not null&&stage.NormalizedName!="SAY"){d.Add(new("FLN252",$"Pipeline stage '{stage.Name}' does not declare implicit input.",stage.Span));return null;}lowered=LowerCommand(e,ctx,b,g,lang,trace,d);}if(lowered.Count!=1){d.Add(new("FLN253",$"Pipeline stage '{stage.Name}' must lower to one command.",stage.Span));return null;}Append(lowered,stage.Span,ctx,g,c,links,map);value=ProducedVariable(e,lowered)??value;}return value;}
private static IReadOnlyList<CommandSyntax>LowerData(SurfaceCommandSyntax s,string input,string output,PromptGrammar g,ICollection<SurfaceDiagnostic>d){CommandSyntax?c=SurfaceDataLowering.Lower(s,input,output,g,d);return c is null?[]:[c];}
private IReadOnlyList<CommandSyntax>LowerCommand(SurfaceCommandSyntax command,LoweringContext ctx,IReadOnlyDictionary<string,Uri>b,PromptGrammar g,LanguageSnapshot lang,InferenceTrace trace,ICollection<SurfaceDiagnostic>d){SurfaceCommandSyntax r=ResolveCommandResources(command,ctx,b);if(r.NormalizedName=="SAY")return[LowerSay(r,g)];if(r.NormalizedName=="POST"){CommandSyntax?x=SurfaceMutationLowering.Post(r,g,d);return x is null?[]:[x];}if(r.NormalizedName=="SAVE"){CommandSyntax?x=SurfaceMutationLowering.Save(r,g,d);return x is null?[]:[x];}if(r.NormalizedName is"GET"or"LOAD")return LowerResources(r,ctx,g,lang,trace,d,r.NormalizedName=="GET"?ResourceReadIntent.Get:ResourceReadIntent.Load);d.Add(new("FLN211",$"Surface command '{command.Name}' does not have a lowering rule yet.",command.Span));return[];}
private IReadOnlyList<CommandSyntax>LowerResources(SurfaceCommandSyntax command,LoweringContext ctx,PromptGrammar g,LanguageSnapshot lang,InferenceTrace trace,ICollection<SurfaceDiagnostic>d,ResourceReadIntent intent){if(command.Values.Count==0){d.Add(new("FLN230",$"{command.Name} requires a resource.",command.Span));return[];}List<CommandSyntax>r=[];foreach(SurfaceValueSyntax v in command.Values){ResourceDescriptor descriptor;try{descriptor=i.InferResource(v,lang,trace);}catch(FormatException e){d.Add(new("FLN232",e.Message,v.Span));continue;}string variable=command.Alias??descriptor.SuggestedVariableName;IResourceProvider?provider=p.Resolve(descriptor);if(provider is null){d.Add(new("FLN236",$"No resource provider handles '{descriptor.Reference.DisplayName}'.",v.Span));continue;}ResourceProviderResult lowered=provider.LowerRead(new(descriptor,variable,command,v,g,intent,ctx.AuthenticationSecret));if(!lowered.IsSuccess){d.Add(new(lowered.ErrorCode!,lowered.ErrorMessage!,v.Span));continue;}r.AddRange(lowered.Commands);}return r;}
private static bool ApplyDirective(SurfaceCommandSyntax command,ref LoweringContext ctx,IDictionary<string,Uri>b,ICollection<SurfaceDiagnostic>d){switch(command.NormalizedName){case"USE":if(command.Values.Count!=1||command.Alias is null||!Uri.TryCreate(command.Values[0].UnquotedText,UriKind.Absolute,out Uri?u)){d.Add(new("FLN241","USE requires absolute URI AS alias.",command.Span));return true;}b[command.Alias]=u;return true;case"RETRY":if(command.Values.Count==1&&int.TryParse(command.Values[0].UnquotedText,out int r)&&r>=0)ctx=ctx with{Retry=r};else d.Add(new("FLN242","Invalid RETRY.",command.Span));return true;case"TIMEOUT":if(command.Values.Count==1)ctx=ctx with{Timeout=command.Values[0].UnquotedText};else d.Add(new("FLN243","Invalid TIMEOUT.",command.Span));return true;case"AUTH":if(command.Values.Count==1&&command.Values[0].UnquotedText.StartsWith("secret:",StringComparison.OrdinalIgnoreCase)&&command.Values[0].UnquotedText[7..].Trim().Length>0)ctx=ctx with{AuthenticationSecret=command.Values[0].UnquotedText[7..].Trim()};else d.Add(new("FLN244","AUTH requires `AUTH secret:name`.",command.Span));return true;default:return false;}}
private static SurfaceCommandSyntax ResolveCommandResources(SurfaceCommandSyntax c,LoweringContext x,IReadOnlyDictionary<string,Uri>b){if(c.NormalizedName!="GET")return c;return c with{Values=c.Values.Select(v=>{string t=v.UnquotedText;if(Uri.TryCreate(t,UriKind.Absolute,out _)||t.Contains(':'))return v;int slash=t.IndexOf('/');string prefix=slash<0?t:t[..slash];if(b.TryGetValue(prefix,out Uri?named))return v with{Text=new Uri(named.ToString().TrimEnd('/')+"/"+(slash<0?string.Empty:t[(slash+1)..])).ToString()};if(x.BaseUri is not null)return v with{Text=new Uri(x.BaseUri,t).ToString()};return v;}).ToArray()};}
private static void Append(IReadOnlyList<CommandSyntax>low,SourceSpan span,LoweringContext ctx,PromptGrammar g,List<CommandSyntax>c,List<CommandLinkSyntax>links,List<SourceMapEntry>map){for(int n=0;n<low.Count;n++){int index=c.Count;c.Add(WithPolicies(low[n],ctx,g,span.Start));map.Add(new(index,"command",span));if(n>0)links.Add(new(index-1,index,CommandLinkKind.Parallel,Token("AND",PromptTokenKind.Word,span.Start)));}}
private static CommandSyntax WithPolicies(CommandSyntax c,LoweringContext x,PromptGrammar g,int p){if(x.Retry is null&&x.Timeout is null)return c;List<PromptToken>t=[..c.AllTokens];if(x.Retry is int r){t.Add(Token("WITH",PromptTokenKind.Word,p));t.Add(Token("RETRY",PromptTokenKind.Word,p));t.Add(Token(r.ToString(),PromptTokenKind.Word,p));}if(x.Timeout is string z){t.Add(Token("WITH",PromptTokenKind.Word,p));t.Add(Token("TIMEOUT",PromptTokenKind.Word,p));t.Add(Token(z,PromptTokenKind.Word,p));}return new(t,g);}private static string?ProducedVariable(SurfaceCommandSyntax s,IReadOnlyList<CommandSyntax>l){if(l.Count!=1||s.NormalizedName is"SAY"or"POST"or"SAVE")return null;PromptToken?token=l[0].AllTokens.FirstOrDefault(i=>i.Kind==PromptTokenKind.Variable);if(token is null)return null;string t=token.Text.TrimEnd('.');return t.Length>=2&&t[0]=='['&&t[^1]==']'?t[1..^1]:null;}private static SurfaceCommandSyntax InjectValue(SurfaceCommandSyntax c,string v)=>c with{Values=[new($"[{v}]",c.Span)]};private static string NextPipe(int c)=>$"__pipe_{c:D4}";private static CommandSyntax LowerSay(SurfaceCommandSyntax c,PromptGrammar g){List<PromptToken>t=[Token("SAY",PromptTokenKind.Word,c.Span.Start)];foreach(SurfaceValueSyntax v in c.Values){string x=SurfacePath(v.Text)?$"\"{{{v.Text}}}\"":v.Text;t.Add(Token(x,Classify(x),v.Span.Start));}return new(t,g);}private static bool SurfacePath(string t){if(t.Length>=2&&t[0] is'"'or'\''&&t[^1]==t[0])return false;try{return ExpressionSyntaxParser.Parse(t)is PropertyExpressionSyntax or IndexExpressionSyntax;}catch{return false;}}private static bool TryResolveBase(string t,Uri?p,out Uri?u){if(Uri.TryCreate(t,UriKind.Absolute,out u))return true;if(p is not null&&Uri.TryCreate(p,t,out u))return true;u=null;return false;}private static PromptToken Token(string t,PromptTokenKind k,int s)=>new(t,k,Math.Max(0,s),0);private static PromptTokenKind Classify(string t)=>t.Length>=2&&t[0]=='['&&t[^1]==']'?PromptTokenKind.Variable:t.Length>=2&&t[0]=='{'&&t[^1]=='}'?PromptTokenKind.Reference:PromptTokenKind.Word;private sealed record LoweringContext(Uri?BaseUri,int?Retry,string?Timeout,string?AuthenticationSecret);}
